/** tracks.ts APRS_CODE_GLYPH: the symbol code → its picture (-1 = none: the code itself is drawn, as the app does). */
inline int glyphFor(char code) {
    switch (code) {
        case '>': return 0;   // car
        case 'j': return 0;   // car
        case 'k': return 1;   // truck
        case 'u': return 1;   // truck
        case 'v': return 1;   // truck
        case 'R': return 1;   // truck
        case 'U': return 1;   // truck
        case 'a': return 1;   // truck
        case 'f': return 1;   // truck
        case '-': return 2;   // house
        case 'K': return 2;   // house
        case 'H': return 2;   // house
        case '#': return 3;   // star
        case '&': return 4;   // diamond
        case '_': return 5;   // cloud
        case 'O': return 6;   // balloon
        case '^': return 7;   // plane
        case '\'': return 7;   // plane
        case 'X': return 8;   // heli
        case 's': return 9;   // boat
        case 'Y': return 9;   // boat
        case 'C': return 9;   // boat
        case '[': return 10;   // person
        case 'b': return 11;   // bike
        case '<': return 11;   // bike
        case 'r': return 12;   // antenna
        case 'y': return 12;   // antenna
        case 'n': return 3;   // star
        default: return -1;
    }
}
